use crate::*;
use base64::{Engine,engine::general_purpose::STANDARD};
pub(crate) fn images(value:&Value)->Result<Vec<Value>>{let Some(items)=value.as_array()else{return Ok(vec![])};if items.len()>3{return Err("一次最多附加 3 张截图。".into());}let mut result=Vec::new();for item in items{let data=item.as_str().ok_or("截图数据无效")?;let encoded=data.strip_prefix("data:image/png;base64,").ok_or("截图须经启动器转换为 PNG")?;if encoded.len()>14*1024*1024{return Err("单张截图超过 10 MB。".into());}let bytes=STANDARD.decode(encoded).map_err(|_|"截图编码无效")?;if bytes.len()>10*1024*1024{return Err("单张截图超过 10 MB。".into());}let decoder=png::Decoder::new(std::io::Cursor::new(&bytes));let reader=decoder.read_info().map_err(|_|"截图不是合法 PNG")?;let info=reader.info();if info.width==0||info.height==0||info.width>2048||info.height>2048{return Err("截图最长边不能超过 2048 像素。".into());}result.push(json!({"type":"image_url","image_url":{"url":data,"detail":"auto"}}));}Ok(result)}
#[cfg(test)]mod tests{use super::*;#[test]fn rejects_large_invalid_or_foreign_data(){assert!(images(&json!(["https://example.com/image.png"])).is_err());assert!(images(&json!(["data:image/png;base64,invalid"])).is_err());assert!(images(&json!(["a","b","c","d"])).is_err());let mut bytes=vec![];{let mut encoder=png::Encoder::new(&mut bytes,1,1);encoder.set_color(png::ColorType::Rgba);encoder.write_header().unwrap().write_image_data(&[0,0,0,255]).unwrap();}let image=format!("data:image/png;base64,{}",STANDARD.encode(bytes));assert_eq!(images(&json!([image])).unwrap().len(),1);}}
